// Returns the maximum element in a non-empty slice.
// Properties satisfied:
// 1) The return value is >= every element in `a`.
// 2) The return value equals some element of `a` (specifically, one encountered while scanning).
fn maxArray(a: &[i32]) -> i32 {
    assert!(!a.is_empty(), "input slice must be non-empty");

    let mut m = a[0];
    for &x in &a[1..] {
        if x > m {
            m = x;
        }
    }
    m
}